@Nc.CaseI.cf_mul : ∀ {F : Type u_1} [inst : CommSemiring F] {k : ℕ} {T : Type u_2} [DecidableEq T] (S : Finset (Fin k))
  (P Q : MvPolynomial (Fin k × T) F) (x : Fin k → T),
  Nc.CaseI.cf S (P * Q) x = ∑ A ∈ S.powerset, Nc.CaseI.cf A P x * Nc.CaseI.cf (S \ A) Q x
@Nc.CaseI.dec_gate : ∀ {F : Type u_1} [inst : CommSemiring F] {k : ℕ} {T : Type u_2} [DecidableEq T]
  {l : ℕ → MvPolynomial (Fin k × T) F} {s : ℕ},
  (∀ γ < s, Nc.IsStep l γ) →
    2 ≤ k → ∀ γ < s, ∀ (S : Finset (Fin k)), 2 * k < 3 * S.card → Nc.CaseI.Dec l s S (Nc.CaseI.cf S (l γ))
