  {P : MvPolynomial (Fin k × T) R} {L : ℕ},
  Computes P L →
    2 ≤ k → ∃ g q, linearPart P = ∑ S with k ≤ 3 * #S ∧ 3 * #S ≤ 2 * k, ∑ δ, linearIn S (g S δ) * linearIn Sᶜ (q S δ)
@lem_balanced_cf : ∀ {R T : Type} [inst : CommSemiring R] [Fintype T] [DecidableEq T] {k : ℕ}
  {P : MvPolynomial (Fin k × T) R} {L : ℕ},
  Computes P L →
    2 ≤ k → ∃ g q, ∀ (y : Fin k → T), cf univ P y = ∑ S ∈ bal univ, ∑ δ, (g S δ fun a => y ↑a) * q S δ fun a => y ↑a
